    doctor_push_interrupted_scan_entries(
        &mut reports,
        data_dir,
        &data_dir.join("doctor").join("tmp"),
        "doctor-tmp-artifact",
    );
    doctor_push_interrupted_scan_entries(
        &mut reports,
        data_dir,
        &data_dir.join("doctor").join("receipts"),
        "doctor-receipt-artifact",
    );
    doctor_push_interrupted_scan_entries(
        &mut reports,
        data_dir,
        &data_dir.join("doctor").join("events"),
        "doctor-event-artifact",
    );
